// Self-signed TLS certificate for the end-to-end server (spec 11.3, R-18).
// One leaf certificate covers every test host; Chromium trusts it through
// `--ignore-certificate-errors-spki-list` (pinned to its key only, not a
// blanket certificate bypass). Generated by `openssl` (LibreSSL on macOS);
// without `openssl` the harness fails explicitly.
import { execFileSync } from "node:child_process";
import { createHash, X509Certificate } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/** Every host the pages are served under (tests map them to 127.0.0.1). */
export const CERT_HOSTS: readonly string[] = [
  "atlas-cloud.test",
  "*.atlas-cloud.test",
  "atlass-cloud.test",
  "evil.test",
  "*.evil.test",
  "atlas-cloud.test.evil.test",
  "accounts.google.com",
  "accounts.google.com.evil.test",
];

export interface TestCert {
  key: string;
  cert: string;
  /** base64(SHA-256(SubjectPublicKeyInfo)), for `--ignore-certificate-errors-spki-list`. */
  spki: string;
}

function hasOpenssl(): boolean {
  try {
    execFileSync("openssl", ["version"], { stdio: "pipe" });
    return true;
  } catch {
    return false;
  }
}

/** Generates (into `dir`) a fresh key and self-signed certificate for `hosts` (default `CERT_HOSTS`). */
export function generateCert(dir: string, hosts: readonly string[] = CERT_HOSTS): TestCert {
  if (!hasOpenssl()) throw new Error("e2e: openssl is required to generate the test certificate");
  mkdirSync(dir, { recursive: true });
  const conf = join(dir, "cert.cnf");
  const keyPath = join(dir, "key.pem");
  const certPath = join(dir, "cert.pem");
  const san = hosts.map((h, i) => `DNS.${i + 1} = ${h}`).join("\n");
  writeFileSync(
    conf,
    [
      "[req]",
      "distinguished_name = dn",
      "x509_extensions = ext",
      "prompt = no",
      "[dn]",
      "CN = OnePass e2e test server",
      "O = OnePass tests (fictional)",
      "[ext]",
      "basicConstraints = critical, CA:FALSE",
      "keyUsage = critical, digitalSignature, keyEncipherment",
      "extendedKeyUsage = serverAuth",
      "subjectAltName = @san",
      "[san]",
      san,
      "",
    ].join("\n"),
  );
  execFileSync(
    "openssl",
    ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-sha256", "-days", "2", "-keyout", keyPath, "-out", certPath, "-config", conf],
    { stdio: "pipe" },
  );
  return loadCert(dir);
}

/** The certificate written by `generateCert` into `dir`. */
export function loadCert(dir: string): TestCert {
  const cert = readFileSync(join(dir, "cert.pem"), "utf8");
  const key = readFileSync(join(dir, "key.pem"), "utf8");
  const der = new X509Certificate(cert).publicKey.export({ type: "spki", format: "der" });
  const spki = createHash("sha256").update(der).digest("base64");
  return { key, cert, spki };
}
